Session.kernel_code:
pub struct Session {
    pub active: bool,
    /// Content-Length of the upload.
    pub declared: u32,
    /// Bytes written so far, contiguous from offset 0.
    pub written: u32,
}

begin.kernel_code:
pub fn begin(current: Session, authorised: bool, has_length: bool, len: u32) -> Option<Session> {
    if !current.active && authorised && has_length && len > 0 && len <= ACTIVE_SIZE {
        Some(Session { active: true, declared: len, written: 0 })
    } else {
        None
    }
}

confirm_boot.kernel_code:
pub fn confirm_boot(state_is_swap: bool, up: bool) -> bool {
    state_is_swap && up
}

token_ok.kernel_code:
pub fn token_ok(given: &[u8; TOKEN_LEN], configured: &[u8; TOKEN_LEN]) -> bool {
    let mut diff: u8 = 0;
    let mut any: u8 = 0;
    let mut i = 0;
    while i < TOKEN_LEN {
        diff |= given[i] ^ configured[i];
        any |= configured[i];
        i += 1;
    }
    diff == 0 && any != 0
}

complete.kernel_code:
pub fn complete(s: Session) -> bool {
    s.active && s.written == s.declared && s.declared > 0
}

abort.kernel_code:
pub fn abort(_s: Session) -> Session {
    IDLE
}

chunk.kernel_code:
pub fn chunk(s: Session, n: u32) -> Option<(u32, Session)> {
    if s.active && n > 0 && n <= s.declared - s.written {
        Some((s.written, Session { active: true, declared: s.declared, written: s.written + n }))
    } else {
        None
    }
}
